abstract class ImportTemplate {

    /** 流程锁死:final 让子类无法改变顺序 */
    public final void run(String source) {
        List<Row> rows = read(source);
        validate(rows);
        int n = save(rows);
        afterSave(n);      // 钩子:默认空实现,子类可选覆盖
        notify(n);
    }

    /** 必须实现的步骤 */
    protected abstract List<Row> read(String source);

    protected abstract void validate(List<Row> rows);

    /** 公共步骤:private,子类不可见也不可改 */
    private int save(List<Row> rows) {
        int n = 0;
        for (Row r : rows) {
            if (db.insert(r)) n++;
        }
        return n;
    }

    /** 钩子:留空,子类按需覆盖 */
    protected void afterSave(int count) { }

    protected void notify(int count) {
        log.info("导入完成:{} 条", count);
    }
}

