public final class OrderSnapshot {

    private final String id;
    private final Date createdAt;
    private final List<String> items;

    public OrderSnapshot(String id, Date createdAt, List<String> items) {
        this.id = Objects.requireNonNull(id, "id");
        // 拷入:别让调用方继续持有同一个 Date
        this.createdAt = new Date(Objects.requireNonNull(createdAt).getTime());
        // copyOf:真拷贝 + 不可变 + 拒绝 null 元素
        this.items = List.copyOf(items);
    }

    public String id() { return id; }

    public Date createdAt() {
        // 拷出:每次给一个新 Date,调用方改了也不影响内部
        return new Date(createdAt.getTime());
    }

    public List<String> items() {
        // List.copyOf 产生的对象本身不可变,可以直接返回
        return items;
    }
}

