import java.util.*;

public final class Maxes {

    /**
     * 取集合最大值。
     * T 必须可比较,且允许与 T 的父类比较(Comparable<? super T>)。
     */
    public static <T extends Comparable<? super T>> T max(Collection<? extends T> items) {
        if (items == null || items.isEmpty()) {
            throw new NoSuchElementException("collection is null or empty");
        }
        Iterator<? extends T> it = items.iterator();
        T best = it.next();
        while (it.hasNext()) {
            T cur = it.next();
            if (cur.compareTo(best) > 0) {
                best = cur;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(3, 9, 2);
        Integer i = max(ints);              // T 推断为 Integer

        Collection<Integer> asNumbers = ints;
        Number n = max(asNumbers);          // T 可推断为 Number,返回值兼容
        System.out.println(i + " " + n);
    }
}

