class MinHeap {
    private int[] a = new int[16];
    private int size;

    public void push(int v) {
        if (size == a.length) {
            a = Arrays.copyOf(a, size << 1);   // 扩容必须重新赋值
        }
        a[size] = v;
        siftUp(size);                          // 先上浮
        size++;                                // 再增加计数
    }

    public int pop() {
        int top = a[0];
        a[0] = a[--size];                      // 末尾补头，size 同时减一
        siftDown(0);
        return top;
    }

    public int peek() { return a[0]; }
    public int size() { return size; }

    private void siftUp(int i) {
        while (i > 0) {
            int p = (i - 1) >>> 1;             // 父节点：0 基下标是 (i-1)/2
            if (a[p] <= a[i]) break;           // 小顶堆：父 <= 子 即满足
            swap(p, i);
            i = p;
        }
    }

    private void siftDown(int i) {
        while (true) {
            int l = (i << 1) + 1;              // 左孩子
            int r = l + 1;                     // 右孩子
            int m = i;                         // 三者中最小者
            if (l < size && a[l] < a[m]) m = l;
            if (r < size && a[r] < a[m]) m = r;
            if (m == i) break;                 // 自己最小，堆序已恢复
            swap(i, m);
            i = m;
        }
    }

    private void swap(int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}

