        E old = (E) a[i];
        int moved = size - i - 1;
        if (moved > 0) System.arraycopy(a, i + 1, a, i, moved);
        a[--size] = null;                // 帮助 GC
        modCount++;                      // 结构变了
        return old;
    }

    public int size() { return size; }
    public Iterator<E> iterator() { return new Itr(); }

    private class Itr implements Iterator<E> {
        int cursor;                      // 下一个要返回的下标
        int lastRet = -1;                // 上一次返回的下标,-1 表示没有
        int expectedModCount = modCount; // 开局快照

        public boolean hasNext() { return cursor != size; }

        @SuppressWarnings("unchecked")
        public E next() {
            checkForComodification();            // ① 先对账
            if (cursor >= size) throw new NoSuchElementException();
            E e = (E) a[cursor];
            lastRet = cursor++;                  // ② 记录并前进
            return e;
        }

        public void remove() {
            if (lastRet < 0) throw new IllegalStateException();
            checkForComodification();
            MyList.this.remove(lastRet);          // ③ 删容器
            expectedModCount = modCount;          // ④ 同步,所以不抛
            cursor = lastRet;                     // ⑤ 后面元素前移,回退一位
            lastRet = -1;                         // ⑥ 禁止连续删
        }

        final void checkForComodification() {
            if (modCount != expectedModCount)
                throw new ConcurrentModificationException();
        }
    }
}
